def generate_all_datees_items(discount_pct=18.0):
    """
    تولید لیست کامل ۱۹۳ قلم کالای لوازم خانگی و آشپزخانه داتیس (Datees)
    با تبدیل قیمت‌های ریال کاتالوگ به تومان و اعمال دقیق درصد تخفیف خرید (پیش‌فرض ۱۸٪)
    """
    mult = 1.0 - (discount_pct / 100.0)
    items = []

    for cat, code, full_name, desc_prefix, prod_rials, cons_rials in datees_raw_catalog:
        sell_price = cons_rials // 10
        buy_price = int(round(sell_price * mult))
        factory_price = prod_rials // 10

        desc = f"{desc_prefix} | لیست داتیس D0251 | درب کارخانه: {factory_price:,} تومان | تخفیف خرید {discount_pct}%"

        items.append({
            'name': full_name,
            'category': cat,
            'brand': 'داتیس (Datees)',
            'sell_price': sell_price,
            'buy_price': buy_price,
            'description': desc
        })

    return items


if __name__ == '__main__':
    items = generate_all_datees_items(18.0)
    print(f'Total Datees items generated: {len(items)}')
    sample = items[0]
    print('Sample item:', sample)
